// CreateInvitation persists a new pending Invitation.
func (s *PostgresStore) CreateInvitation(ctx context.Context, inv *Invitation) error {
	err := s.q.CreateInvitation(ctx, db.CreateInvitationParams{
		Token:     inv.token,
		OrgGrn:    inv.orgGRN.String(),
		Role:      string(inv.role),
		CreatedBy: inv.createdBy.String(),
		CreatedAt: stamp(inv.createdAt),
		ExpiresAt: stamp(inv.expiresAt),
	})
	return classify(err, "create invitation", nil, nil)
}

// GetInvitation returns the Invitation with the given token, or
// ErrInvitationNotFound.
func (s *PostgresStore) GetInvitation(ctx context.Context, token string) (*Invitation, error) {
	row, err := s.q.GetInvitation(ctx, token)
	if err != nil {
		return nil, classify(err, "get invitation", ErrInvitationNotFound, nil)
	}
	return rowToInvitation(row)
}

// AcceptInvitation marks a pending Invitation accepted by the user.
// An unknown token yields ErrInvitationNotFound; an already-accepted
// token yields ErrInvitationAccepted.
func (s *PostgresStore) AcceptInvitation(ctx context.Context, token string, userGRN grn.GRN) (*Invitation, error) {
	row, err := s.q.AcceptInvitation(ctx, db.AcceptInvitationParams{
		Token:      token,
		AcceptedBy: pgtype.Text{String: userGRN.String(), Valid: true},
		AcceptedAt: stamp(time.Now().UTC()),
	})
	if errors.Is(err, pgx.ErrNoRows) {
		// The update only misses when the token is unknown or the row
		// is already accepted; look it up to tell the two apart.
		if _, getErr := s.q.GetInvitation(ctx, token); getErr != nil {
			return nil, classify(getErr, "accept invitation", ErrInvitationNotFound, nil)
		}
		return nil, ErrInvitationAccepted
	}
	if err != nil {
		return nil, classify(err, "accept invitation", nil, nil)
	}
	return rowToInvitation(row)
}

// rowToOrg converts a sqlc row into the domain aggregate. A stored
// GRN that no longer parses is data corruption, hence internal.
func rowToOrg(row db.Org) (*Organization, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "org row grn", errorx.KindInternal)
	}
	return &Organization{grn: g, name: row.Name, createdAt: row.CreatedAt.Time, updatedAt: row.UpdatedAt.Time}, nil
}

func rowToGroup(row db.Group) (*Group, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "group row grn", errorx.KindInternal)
	}
	og, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "group row org grn", errorx.KindInternal)
	}
	return &Group{
		grn:       g,
		name:      row.Name,
		orgGRN:    og,
		roles:     row.Roles,
		policies:  row.Policies,
		createdAt: row.CreatedAt.Time,
		updatedAt: row.UpdatedAt.Time,
	}, nil
}

func rowToProject(row db.Project) (*Project, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "project row grn", errorx.KindInternal)
	}
	og, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "project row org grn", errorx.KindInternal)
	}
	return &Project{
		grn:       g,
		name:      row.Name,
		orgGRN:    og,
		roles:     row.Roles,
		policies:  row.Policies,
		createdAt: row.CreatedAt.Time,
		updatedAt: row.UpdatedAt.Time,
	}, nil
}

func rowToMembership(row db.OrgMember) (*Membership, error) {
	role, err := ParseRole(row.Role)
	if err != nil {
		return nil, errorx.Wrap(err, "member row role", errorx.KindInternal)
	}
	og, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "member row org grn", errorx.KindInternal)
	}
	ug, err := grn.Parse(row.UserGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "member row user grn", errorx.KindInternal)
	}
	return &Membership{
		orgGRN:    og,
		userGRN:   ug,
		role:      role,
		createdAt: row.CreatedAt.Time,
	}, nil
}

func rowToInvitation(row db.Invitation) (*Invitation, error) {
	role, err := ParseRole(row.Role)
	if err != nil {
		return nil, errorx.Wrap(err, "invitation row role", errorx.KindInternal)
	}
	og, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "invitation row org grn", errorx.KindInternal)
	}
	cb, err := grn.Parse(row.CreatedBy)
	if err != nil {
		return nil, errorx.Wrap(err, "invitation row creator grn", errorx.KindInternal)
	}
	inv := &Invitation{
		token:     row.Token,
		orgGRN:    og,
		role:      role,
		createdBy: cb,
		createdAt: row.CreatedAt.Time,
		expiresAt: row.ExpiresAt.Time,
	}
	if row.AcceptedBy.Valid {
		ab, err := grn.Parse(row.AcceptedBy.String)
		if err != nil {
			return nil, errorx.Wrap(err, "invitation row acceptor grn", errorx.KindInternal)
		}
		inv.acceptedBy = ab
	}
	if row.AcceptedAt.Valid {
		inv.acceptedAt = row.AcceptedAt.Time
	}
	return inv, nil
}

func parseGRNs(ss []string, op string) ([]grn.GRN, error) {
	out := make([]grn.GRN, 0, len(ss))
	for _, s := range ss {
		g, err := grn.Parse(s)
		if err != nil {
			return nil, errorx.Wrap(err, op, errorx.KindInternal)
		}
		out = append(out, g)
	}
	return out, nil
}

// classify maps driver errors onto errorx kinds: missing rows become
// the notFound sentinel, unique violations become the conflict
// sentinel when given (otherwise already-exists), foreign-key
// violations become not-found.
func classify(err error, op string, notFound, conflict error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) && notFound != nil {
		return notFound
	}
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		switch pgErr.Code {
		case "23505":
			if conflict != nil {
				return conflict
			}
			return errorx.Wrap(err, "org store: "+op, errorx.KindAlreadyExists)
		case "23503":
			return errorx.Wrap(err, "org store: "+op+": referenced row missing", errorx.KindNotFound)
		}
	}
	return errorx.Wrap(err, "org store: "+op)
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}

// strs normalizes a nil slice to empty: pgx encodes a nil slice as
// NULL, which the NOT NULL array columns reject.
func strs(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// text converts a *string patch field to a nullable text.
func text(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}

// limit converts a ListFilter limit: 0 means "no limit" (SQL NULL).
func limit(n int) pgtype.Int4 {
	if n <= 0 {
		return pgtype.Int4{}
	}
	return pgtype.Int4{Int32: int32(n), Valid: true}
}
